// Парсинг CSV данных
const csvContent = $input.first().binary.data.data;
const csvText = Buffer.from(csvContent, 'base64').toString('utf8');

// Разбиваем на строки
const lines = csvText.split('\n').filter(line => line.trim());
const headers = lines[0].split(',').map(h => h.trim());

// Обрабатываем каждую строку данных
const processedData = [];
for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',').map(v => v.trim());

  if (values.length === headers.length) {
    const row = {};
    headers.forEach((header, index) => {
      let value = values[index];

      // Очищаем кавычки если есть
      if (value.startsWith('"') && value.endsWith('"')) {
        value = value.slice(1, -1);
      }

      // Преобразуем числовые значения
      if (header.includes('price') || header.includes('amount') || header.includes('quantity')) {
        value = parseFloat(value) || 0;
      } else if (header.includes('date')) {
        // Пытаемся распарсить дату
        const date = new Date(value);
        value = isNaN(date.getTime()) ? value : date.toISOString();
      }

      row[header] = value;
    });

    // Добавляем метаданные
    row.processed_at = new Date().toISOString();
    row.row_number = i;
    row.data_id = `csv_${Date.now()}_${i}`;

    processedData.push({ json: row });
  }
}

return processedData;

// Валидация и очистка данных
const items = $input.all();
const validatedItems = [];
const errors = [];

for (const item of items) {
  const data = item.json;
  const errors_for_item = [];

  // Проверяем обязательные поля
  const requiredFields = ['customer_name', 'product', 'price', 'quantity', 'date'];
  requiredFields.forEach(field => {
    if (!data[field] || data[field] === '') {
      errors_for_item.push(`Отсутствует обязательное поле: ${field}`);
    }
  });

  // Валидация цены
  if (data.price && (isNaN(data.price) || data.price < 0)) {
    errors_for_item.push('Некорректная цена');
  }

  // Валидация количества
  if (data.quantity && (isNaN(data.quantity) || data.quantity < 0)) {
    errors_for_item.push('Некорректное количество');
  }

  // Валидация email если есть
  if (data.email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(data.email)) {
      errors_for_item.push('Некорректный email');
    }
  }

  if (errors_for_item.length === 0) {
    // Вычисляем общую сумму
    data.total_amount = (data.price || 0) * (data.quantity || 0);

    // Определяем категорию заказа
    if (data.total_amount > 1000) {
      data.order_category = 'large';
    } else if (data.total_amount > 100) {
      data.order_category = 'medium';
    } else {
      data.order_category = 'small';
    }

    validatedItems.push({ json: data });
  } else {
    errors.push({
      row: data.row_number,
      data_id: data.data_id,
      errors: errors_for_item
    });
  }
}

// Если есть ошибки, сохраняем их
if (errors.length > 0) {
  // Здесь можно отправить ошибки в отдельную таблицу или файл
  console.log('Найдены ошибки валидации:', errors);
}

return validatedItems;

// Генерация отчета
const items = $input.all();

if (items.length === 0) {
  return [{ json: { message: 'Нет данных для обработки' } }];
}

// Статистика
const stats = {
  total_records: items.length,
  total_amount: items.reduce((sum, item) => sum + (item.json.total_amount || 0), 0),
  average_order: 0,
  categories: {},
  top_products: {},
  processing_time: new Date().toISOString()
};

// Вычисляем средний чек
stats.average_order = stats.total_amount / stats.total_records;

// Подсчитываем категории заказов
items.forEach(item => {
  const category = item.json.order_category;
  stats.categories[category] = (stats.categories[category] || 0) + 1;

  const product = item.json.product;
  stats.top_products[product] = (stats.top_products[product] || 0) + 1;
});

// Топ-5 продуктов
const topProducts = Object.entries(stats.top_products)
  .sort(([,a], [,b]) => b - a)
  .slice(0, 5)
  .map(([product, count]) => ({ product, count }));

stats.top_products = topProducts;

return [{ json: stats }];

